@layer cojeev-states {
[data-slot="progress"].v-track {
  --c: var(--v-yellow);
  position: relative;
  display: block;
  width: 100%;
  min-width: 0;
  height: var(--track-h, 12px);
  flex: 1;
  border-radius: var(--r-pill);
  color: var(--c);
}
[data-slot="progress"].-lg {
  height: var(--track-h-lg, 20px);
}
[data-slot="progress"].-sm {
  height: var(--track-h-sm, 6px);
}
[data-slot="progress"] > [data-slot="progress-indicator"] {
